for(const row of [['Manúbrio do esterno','Porção superior e mais larga.','Manubrium of sternum'],['Corpo do esterno','Porção central alongada.','Body of sternum'],['Processo xifoide','Extremidade inferior do esterno.','Xiphoid process']])add('sternum',row[0],'Qual parte do esterno está destacada?',row[1],row[2],true);
