add('pelvis','Promontório do sacro','Borda anterior saliente do corpo de S1.','','Sacrum');
add('pelvis','Asa do sacro','Expansão lateral à parte superior do corpo de S1.','','Sacrum');
add('pelvis','Sínfise púbica','Articulação mediana entre os púbis direito e esquerdo.','É uma articulação cartilagínea, não um acidente de um osso isolado.','Hip bone.r');
const vertebra=[
['Corpo vertebral','Porção anterior volumosa.'],['Arco vertebral','Conjunto posterior formado por pedículos e lâminas.'],['Pedículo','Ponte entre corpo e arco posterior.'],['Lâmina','Parte do arco entre processos transverso e espinhoso.'],['Forame vertebral','Abertura entre corpo e arco.'],['Processo espinhoso','Projeção posterior mediana.'],['Processo transverso','Projeção lateral de cada lado.'],['Processos articulares superiores','Projeções articulares voltadas à vértebra acima.'],['Processos articulares inferiores','Projeções articulares voltadas à vértebra abaixo.'],['Incisuras vertebrais','Reentrâncias superior e inferior dos pedículos.']
];
for(const[a,p]of vertebra)add('vertebra',a,p,'A identificação aqui é pela descrição; gire a vértebra para conferir a orientação.','Vertebra L3');
add('vertebra','Forame intervertebral','Abertura formada entre vértebras adjacentes para passagem de nervos espinais.','Não é o forame vertebral de uma vértebra isolada.','Vertebra L3');
