const theory={
planes:[['Posição anatômica','Qual posição é a referência para descrever o corpo?','Em pé, olhar à frente, membros superiores ao lado do corpo e palmas voltadas para a frente.'],['Anterior e posterior','O que significam anterior e posterior?','Anterior = à frente; posterior = atrás. Posteroinferior = atrás e abaixo.'],['Medial e lateral','Como diferenciar medial de lateral?','Medial: perto do plano mediano. Lateral: afastado dele.'],['Proximal e distal','Como diferenciar proximal de distal nos membros?','Proximal: mais próximo da raiz do membro; distal: mais distante.'],['Plano sagital','Qual plano separa direita e esquerda?','O mediano é o sagital que passa pelo meio, em metades direita e esquerda.'],['Plano frontal (coronal)','Qual plano separa anterior e posterior?','Imagine dividir frente e costas.'],['Plano transversal','Qual plano separa superior e inferior?','Também chamado horizontal ou axial em muitos contextos.'],['Eixo laterolateral (transversal)','Flexão e extensão: qual eixo e plano predominantes?','Eixo laterolateral; plano sagital.'],['Eixo anteroposterior (sagital)','Abdução e adução: qual eixo e plano predominantes?','Eixo anteroposterior; plano frontal.'],['Eixo longitudinal (vertical)','Rotações medial e lateral: qual eixo e plano predominantes?','Eixo longitudinal; plano transversal.']],
skeleton:[['Sustentação, proteção e movimento','Cite três funções mecânicas do esqueleto.','Também armazena minerais; a medula vermelha realiza hematopoiese.'],['206 ossos: 80 axiais e 126 apendiculares','Qual é a contagem convencional do esqueleto adulto?','Há variações individuais. O número de peças do modelo 3D não é essa contagem.'],['Ossos longos','Como se classificam fêmur e metacarpais pela forma?','Comprimento predomina. Longo não significa necessariamente grande.'],['Ossos curtos','Como se classificam a maioria dos carpais e tarsais?','Dimensões semelhantes; o pisiforme é sesamoide.'],['Ossos planos','Como se classificam esterno e escápula?','Finamente expandidos, com papel protetor ou de fixação muscular.'],['Ossos irregulares','Como se classificam as vértebras?','Formato complexo.'],['Ossos sesamoides','Como se classifica a patela?','Desenvolvem-se em tendões.'],['Diáfise e epífises','Como se chamam o corpo e as extremidades de um osso longo?','Diáfise = corpo; epífises = extremidades; metáfises são regiões de transição.']],
joints:[['Fibrosas, cartilagíneas e sinoviais','Quais são as três classes estruturais das articulações?','A classificação considera o tecido de união e a presença de cavidade sinovial.'],['Sinartrose, anfiartrose e diartrose','Quais são as classes funcionais de mobilidade?','Respectivamente: imóvel, pouco móvel e livremente móvel.'],['Sutura','Qual articulação fibrosa une muitos ossos do crânio?','Não confunda sutura com articulação sinovial.'],['Sindesmose','Qual articulação fibrosa usa ligamento ou membrana interóssea?','Exemplo: articulação tibiofibular distal.'],['Gonfose','Qual articulação une o dente ao alvéolo?','União fibrosa pelo ligamento periodontal.'],['Sincondrose','Qual união cartilagínea possui cartilagem hialina?','Exemplo: placa epifisária durante o crescimento.'],['Sínfise','Qual união cartilagínea inclui fibrocartilagem?','Exemplo: sínfise púbica.']],
synovial:[['Cavidade, cápsula, cartilagem e líquido sinovial','Quais componentes básicos caracterizam uma articulação sinovial?','Cartilagem recobre superfícies; membrana sinovial reveste internamente a cápsula, exceto superfícies cartilagíneas.'],['Plana','Qual tipo permite principalmente deslizamentos?','Exemplo: muitas articulações intercarpais.'],['Gínglimo (dobradiça)','Qual tipo permite principalmente flexão e extensão em um eixo?','Exemplo: interfalângicas.'],['Trocoide (pivô)','Qual tipo permite rotação em um eixo?','Exemplo: radioulnar proximal.'],['Elipsoide (condilar)','Qual tipo biaxial caracteriza a articulação radiocarpal?','Permite flexão/extensão e abdução/adução.'],['Selar','Qual tipo caracteriza a carpometacarpal do polegar?','Superfícies em sela; biaxial, participa da oposição.'],['Esferoide','Qual tipo multiaxial caracteriza ombro e quadril?','Cabeça arredondada em cavidade; permite rotações.']],
muscles:[['Estriado esquelético','Qual tecido muscular geralmente move o esqueleto sob controle voluntário?','Fibras longas e multinucleadas.'],['Estriado cardíaco','Qual tecido muscular forma o miocárdio?','Involuntário, estriado, com discos intercalares.'],['Liso','Qual tecido não estriado está em paredes de vísceras e vasos?','Controle involuntário.'],['Tendão','Qual estrutura de tecido conjuntivo transmite força muscular ao osso?','Ligamentos, em geral, unem ossos entre si.'],['Endomísio, perimísio e epimísio','Quais envoltórios cercam fibra, fascículo e músculo inteiro?','Nessa ordem: endomísio → perimísio → epimísio.']],
actions:[['Agonista','Como se chama o principal produtor de um movimento?','Também chamado motor primário.'],['Antagonista','Como se chama o músculo que se opõe a uma ação?','Seu papel depende do movimento analisado.'],['Sinergista e fixador','Quem auxilia a ação e quem estabiliza uma parte?','Sinergista auxilia; fixador estabiliza a origem ou uma região.'],['Origem e inserção','Quais referências descrevem as fixações musculares?','Usualmente origem é menos móvel e inserção mais móvel; a relação pode se inverter.'],['Contração concêntrica','O músculo ativo encurta. Qual é o tipo?','Exemplo: flexores do cotovelo ao levantar uma carga.'],['Contração excêntrica','O músculo ativo alonga sob tensão. Qual é o tipo?','Exemplo: flexores ao baixar uma carga lentamente.'],['Contração isométrica','Há tensão sem mudança apreciável do comprimento. Qual é o tipo?','Exemplo: sustentar uma carga parada.']]
};
for(const [topic,rows]of Object.entries(theory))for(const[a,p,n]of rows)add(topic,a,p,n);
export function cardPool(exam,topic='all',weakOnly=false,progress={}){return cards.filter(c=>topics.find(t=>t.id===c.topic).exam===exam&&(topic==='all'||c.topic===topic)&&(!weakOnly||progress[c.id]===false));}
export function shuffle(items,random=Math.random){const result=[...items];for(let i=result.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
export function loadProgress(storage){try{const value=JSON.parse(storage.getItem('anatomy-exam-progress')||'{}');return Object.fromEntries(cards.filter(c=>typeof value?.[c.id]==='boolean').map(c=>[c.id,value[c.id]]));}catch{return {};}}

export function contextNames(card,manifest){
 if(['hand','foot'].includes(card.topic))return manifest.meshes.filter(m=>m.topic===card.topic&&m.name.endsWith('.r')).map(m=>m.name);
 if(card.topic==='sternum')return manifest.meshes.filter(m=>m.topic==='sternum').map(m=>m.name);
 return card.bone?[card.bone]:[];
}
